//! Parity against three independent references, on the fixture the R `correlation_operator`
//! ships (`crabs`: x = `x_values`, y = `y_values`, rows = `sp`, columns = `variable`, 10 cells
//! of 100 pairs).
//!
//! * `test_1_out_1.csv` — every output column, generated by `dev/make_goldens.py` (numpy +
//!   scipy, two-pass moments, closed forms). This is also the platform unit test's golden.
//! * `r_crosscheck.csv` — the CCC and its interval from a separate base-R implementation of
//!   Lin 1989 (`dev/ccc_check.R`).
//! * `r_cortest_out.csv` — the R `correlation_operator`'s own published golden: its Pearson
//!   coefficient must equal our `pearson_r`.
//!
//! `.ri` indexes `test_1_out_3.csv` (the row facet table) and `.ci` indexes
//! `test_1_out_2.csv`, in file order, which is how the golden is reproduced without a Tercen
//! instance.
use lin_ccc_operator::Cells;
use lin_ccc_operator::algorithm::z_for_level;
use lin_ccc_operator::output::{COLUMNS, LABEL_COLUMNS, Row, value};
use std::collections::HashMap;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests");

fn read_csv(path: &str) -> (Vec<String>, Vec<Vec<String>>) {
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    let mut lines = text.lines();
    let unquote = |s: &str| s.trim().trim_matches('"').to_string();
    let header: Vec<String> = lines.next().unwrap().split(',').map(unquote).collect();
    let rows = lines
        .filter(|l| !l.trim().is_empty())
        .map(|l| l.split(',').map(unquote).collect())
        .collect();
    (header, rows)
}

fn col(header: &[String], name: &str) -> usize {
    header
        .iter()
        .position(|h| h == name)
        .unwrap_or_else(|| panic!("no column {name} in {header:?}"))
}

/// Result rows keyed by (row level, column level), plus the two level orders.
type Computed = (HashMap<(String, String), Row>, Vec<String>, Vec<String>);

/// Run the operator's accumulation on the fixture.
fn computed() -> Computed {
    let row_levels: Vec<String> = read_csv(&format!("{DIR}/test_1_out_3.csv"))
        .1
        .into_iter()
        .map(|r| r[0].clone())
        .collect();
    let col_levels: Vec<String> = read_csv(&format!("{DIR}/test_1_out_2.csv"))
        .1
        .into_iter()
        .map(|r| r[0].clone())
        .collect();
    let (h, rows) = read_csv(&format!("{DIR}/test_1_in.csv"));
    let (ix, iy, isp, ivar) = (
        col(&h, "x_values"),
        col(&h, "y_values"),
        col(&h, "sp"),
        col(&h, "variable"),
    );
    let (mut ri, mut ci, mut x, mut y) = (vec![], vec![], vec![], vec![]);
    for r in &rows {
        ri.push(row_levels.iter().position(|l| *l == r[isp]).unwrap() as i32);
        ci.push(col_levels.iter().position(|l| *l == r[ivar]).unwrap() as i32);
        x.push(r[ix].parse::<f64>().unwrap());
        y.push(r[iy].parse::<f64>().unwrap());
    }
    let mut cells = Cells::new(row_levels.len(), col_levels.len());
    // Feed in uneven chunks, as the stream would.
    for range in [0..137, 137..600, 600..rows.len()] {
        cells
            .add(
                &ri[range.clone()],
                &ci[range.clone()],
                &x[range.clone()],
                &y[range],
            )
            .unwrap();
    }
    let out = cells
        .finish(z_for_level(0.95))
        .into_iter()
        .map(|r| {
            (
                (
                    row_levels[r.ri as usize].clone(),
                    col_levels[r.ci as usize].clone(),
                ),
                r,
            )
        })
        .collect();
    (out, row_levels, col_levels)
}

fn rel(a: f64, b: f64) -> f64 {
    (a - b).abs() / b.abs().max(1e-300)
}

#[test]
fn every_column_matches_the_numpy_golden() {
    let (got, row_levels, col_levels) = computed();
    let (h, golden) = read_csv(&format!("{DIR}/test_1_out_1.csv"));
    assert_eq!(golden.len(), 10);
    assert_eq!(got.len(), 10, "one result row per non-empty cell");
    let mut worst = 0.0f64;
    for g in &golden {
        let ri: usize = g[col(&h, ".ri")].parse().unwrap();
        let ci: usize = g[col(&h, ".ci")].parse().unwrap();
        let r = &got[&(row_levels[ri].clone(), col_levels[ci].clone())];
        assert_eq!((r.ri as usize, r.ci as usize), (ri, ci));
        for name in COLUMNS {
            let want: f64 = g[col(&h, &format!("ds0.{name}"))].parse().unwrap();
            let have = value(&r.stats, name);
            let e = rel(have, want);
            assert!(
                e < 1e-11,
                "cell ({ri},{ci}) {name}: {have} vs golden {want} (rel {e:e})"
            );
            worst = worst.max(e);
        }
    }
    for g in &golden {
        let ri: usize = g[col(&h, ".ri")].parse().unwrap();
        let ci: usize = g[col(&h, ".ci")].parse().unwrap();
        assert_eq!(
            g[col(&h, "ds0.row_label")],
            row_levels[ri],
            "row label of ({ri},{ci})"
        );
        assert_eq!(
            g[col(&h, "ds0.column_label")],
            col_levels[ci],
            "column label of ({ri},{ci})"
        );
    }
    println!("numpy golden: 10 cells x 9 columns, worst relative difference {worst:e}");
}

#[test]
fn ccc_and_interval_match_an_independent_r_implementation() {
    let (got, _, _) = computed();
    let (h, rows) = read_csv(&format!("{DIR}/r_crosscheck.csv"));
    assert_eq!(rows.len(), 10);
    for r in &rows {
        let key = (r[col(&h, "sp")].clone(), r[col(&h, "variable")].clone());
        let s = &got[&key].stats;
        for (name, have) in [
            ("ccc", s.ccc),
            ("lo", s.ccc_lower),
            ("hi", s.ccc_upper),
            ("r", s.pearson_r),
        ] {
            let want: f64 = r[col(&h, name)].parse().unwrap();
            // the R file is written with 15 significant digits
            assert!(
                rel(have, want) < 1e-12,
                "{key:?} {name}: {have} vs R {want}"
            );
        }
    }
}

#[test]
fn pearson_part_matches_the_r_correlation_operator_golden() {
    let (got, row_levels, col_levels) = computed();
    let (h, rows) = read_csv(&format!("{DIR}/r_cortest_out.csv"));
    for g in &rows {
        let ri: usize = g[col(&h, ".ri")].parse().unwrap();
        let ci: usize = g[col(&h, ".ci")].parse().unwrap();
        let want: f64 = g[col(&h, "ds0.cor_coef")].parse().unwrap();
        let have = got[&(row_levels[ri].clone(), col_levels[ci].clone())]
            .stats
            .pearson_r;
        assert!(
            rel(have, want) < 1e-12,
            "cell ({ri},{ci}): r {have} vs cor.test {want}"
        );
    }
}

#[test]
fn the_decomposition_holds_on_every_cell() {
    // ρc = r · Cb by definition; a regression in either part breaks it.
    let (got, _, _) = computed();
    for r in got.values() {
        let s = &r.stats;
        assert!(rel(s.pearson_r * s.bias_correction, s.ccc) < 1e-12);
        assert!(s.ccc_lower < s.ccc && s.ccc < s.ccc_upper);
        assert!(s.ba_lower < s.ba_bias && s.ba_bias < s.ba_upper);
        assert_eq!(s.n, 100);
    }
}

/// `operator.json` is hand-written and is what the platform shows before the step runs
/// (`DataStep.getPredictedAttributes`), so it is checked against the code.
#[test]
fn operator_spec_matches_the_code() {
    let spec: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/operator.json")).unwrap(),
    )
    .unwrap();

    let props = spec["properties"].as_array().unwrap();
    let names: Vec<&str> = props.iter().map(|p| p["name"].as_str().unwrap()).collect();
    assert_eq!(names, ["confidence_level"]);
    let default = props[0]["defaultValue"].as_f64().unwrap();
    assert_eq!(
        default,
        lin_ccc_operator::props::Settings::default().confidence_level,
        "operator.json and Settings::default() disagree on confidence_level"
    );

    let attrs: Vec<(String, String)> = spec["operatorSpec"]["outputSpecsV2"][0]["joinOperators"][0]
        ["rightRelation"]["attributes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|a| {
            (
                a["name"].as_str().unwrap().to_string(),
                a["type"].as_str().unwrap().to_string(),
            )
        })
        .collect();
    let want: Vec<(String, String)> = COLUMNS
        .iter()
        .map(|c| {
            (
                c.to_string(),
                if *c == "n" { "int32" } else { "double" }.to_string(),
            )
        })
        .collect();
    let mut want = want;
    want.extend(
        LABEL_COLUMNS
            .iter()
            .map(|c| (c.to_string(), "string".to_string())),
    );
    assert_eq!(
        attrs, want,
        "declared output attributes drifted from output::COLUMNS + LABEL_COLUMNS"
    );

    let axis = spec["operatorSpec"]["inputSpecs"][0]["axis"][0]["metaFactors"]
        .as_array()
        .unwrap();
    let mappings: Vec<&str> = axis
        .iter()
        .map(|m| m["crosstabMapping"].as_str().unwrap())
        .collect();
    assert_eq!(mappings, ["y", "x"], "both axes are required inputs");

    let container = spec["container"].as_str().unwrap();
    let version = env!("CARGO_PKG_VERSION");
    assert_eq!(
        container,
        format!("ghcr.io/tercen/lin_ccc_operator:{version}"),
        "operator.json must pin the image of the crate version (release rule)"
    );

    // the platform unit test's golden sidecar types the same columns
    let sidecar: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(format!("{DIR}/test_1_out_1.csv.schema")).unwrap(),
    )
    .unwrap();
    let typed: Vec<(String, String)> = sidecar["columns"]
        .as_array()
        .unwrap()
        .iter()
        .skip(2)
        .map(|c| {
            (
                c["name"]
                    .as_str()
                    .unwrap()
                    .trim_start_matches("ds0.")
                    .to_string(),
                c["type"].as_str().unwrap().to_string(),
            )
        })
        .collect();
    assert_eq!(
        typed, want,
        "test_1_out_1.csv.schema drifted from the output columns"
    );
}

/// The memory model is what the platform books. Check its shape and that it covers a run the
/// operator's structure implies: a ~20 MB static binary, one decoded chunk of 200k values
/// (~40 MB through rustson), and 48 bytes of accumulator per cell.
#[test]
fn memory_model_is_well_formed_and_covers_the_structure() {
    let m: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/memory_model.json"))
            .unwrap(),
    )
    .unwrap();
    assert_eq!(m["kind"], "OperatorEstimateModel");
    let f = &m["features"][0];
    assert_eq!(f["kind"], "Feature");
    assert_eq!(f["name"], "n_main");
    let (intercept, offset) = (
        m["intercept"].as_f64().unwrap(),
        m["offset"].as_f64().unwrap(),
    );
    let booked_mb = |n_values: f64| intercept * n_values + 1.5 * offset;
    // the worst case for accumulators is one value per cell (dense table of n_values cells)
    let need_mb = |n_values: f64| 20.0 + 40.0 + n_values * 48.0 / 1e6;
    // Up to 10 M values; beyond, a one-value-per-cell projection is not a CCC use case.
    for n in [1e3, 1e5, 1e6, 1e7] {
        assert!(
            booked_mb(n) >= 1.3 * need_mb(n),
            "n_main {n}: books {} MB for a need of {} MB",
            booked_mb(n),
            need_mb(n)
        );
    }
}

/// Pairwise mode against `dev/make_pairwise_golden.py`: five samples on rows and columns,
/// paired on the observation label, one observation missing from one sample. The rows are fed
/// in the layout the platform uses (every value on its own sample's diagonal cell).
#[test]
fn pairwise_mode_matches_the_numpy_golden() {
    use lin_ccc_operator::pairwise::Collector;
    let (h, rows) = read_csv(&format!("{DIR}/pairwise_in.csv"));
    let (io, iv, ival) = (
        col(&h, "observation"),
        col(&h, "variable"),
        col(&h, "value"),
    );
    let mut samples: Vec<String> = rows.iter().map(|r| r[iv].clone()).collect();
    samples.sort();
    samples.dedup();
    let idx: Vec<i32> = rows
        .iter()
        .map(|r| samples.iter().position(|s| *s == r[iv]).unwrap() as i32)
        .collect();
    let keys: Vec<String> = rows.iter().map(|r| r[io].clone()).collect();
    let y: Vec<f64> = rows.iter().map(|r| r[ival].parse().unwrap()).collect();
    let mut c = Collector::default();
    c.add(&idx, &idx, &keys, &y);
    let (got, summary) = c
        .finish(samples.len(), samples.len(), z_for_level(0.95))
        .unwrap();
    assert_eq!(summary.observations, 100);
    assert_eq!(summary.duplicates, 0);

    let (gh, golden) = read_csv(&format!("{DIR}/pairwise_out.csv"));
    assert_eq!(golden.len(), 25);
    assert_eq!(got.len(), 25);
    for g in &golden {
        let ri: i32 = g[col(&gh, ".ri")].parse().unwrap();
        let ci: i32 = g[col(&gh, ".ci")].parse().unwrap();
        let r = got.iter().find(|r| r.ri == ri && r.ci == ci).unwrap();
        let n: u64 = g[col(&gh, "n")].parse().unwrap();
        assert_eq!(r.stats.n, n, "cell ({ri},{ci}) pair count");
        for (name, have) in [("ccc", r.stats.ccc), ("ba_bias", r.stats.ba_bias)] {
            let want: f64 = g[col(&gh, name)].parse().unwrap();
            let e = (have - want).abs() / want.abs().max(1e-12);
            assert!(e < 1e-11, "cell ({ri},{ci}) {name}: {have} vs {want}");
        }
    }
}
